for path,content in [(base/'src/forumFlow/readyQueue.mjs',"// Interleave first reads, unfinished page scans and incremental polls. An\n// unbounded list of next_at=0 URLs must not starve an existing scan cursor.\nexport function selectReadyForumUrls(db,site,limit,cursors,now=Date.now()){\n if(!Number.isSafeInteger(limit)||limit<0)throw Error('FORUM_INVALID_READY_LIMIT');\n if(!limit)return [];\n const groups=[\n  db.prepare('SELECT * FROM forum_urls WHERE site=? AND processed=0 AND next_at=0 AND resume_url IS NULL ORDER BY seen,native_id LIMIT ?').all(site,limit),\n  db.prepare('SELECT * FROM forum_urls WHERE site=? AND processed=0 AND next_at<=? AND resume_url IS NOT NULL ORDER BY next_at,seen,native_id LIMIT ?').all(site,now,limit),\n  db.prepare('SELECT * FROM forum_urls WHERE site=? AND processed=0 AND next_at<=? AND next_at!=0 AND resume_url IS NULL ORDER BY next_at,seen,native_id LIMIT ?').all(site,now,limit)\n ];\n const positions=[0,0,0],selected=[];let cursor=cursors.get(site)||0,empty=0;\n while(selected.length<limit&&empty<3){const group=cursor;cursor=(cursor+1)%3;if(positions[group]<groups[group].length){selected.push(groups[group][positions[group]++]);empty=0;}else empty++;}\n cursors.set(site,cursor);return selected;\n}\nexport function hasUnscheduledForumUrl(db,site){return !!db.prepare('SELECT 1 FROM forum_urls WHERE site=? AND processed=0 AND next_at=0 AND resume_url IS NULL LIMIT 1').get(site);}\n"),(base/'test/forum-ready-fairness.test.mjs','import test from \'node:test\';import assert from \'node:assert/strict\';\nimport {ForumState} from \'../src/forumFlow/state.mjs\';import {ForumRuntime} from \'../src/forumFlow/runtime.mjs\';\nconst site=\'forum.test\';\nasync function fixture(){const s=await ForumState.open(\':memory:\');for(let n=1;n<=50;n++)s.enqueue(site,\'https://forum.test/threads/new.\'+n,String(n));s.enqueue(site,\'https://forum.test/threads/resume.100\',\'100\');s.enqueue(site,\'https://forum.test/threads/poll.200\',\'200\');s.db.exec("UPDATE forum_urls SET next_at=1,resume_url=\'https://forum.test/threads/resume.100/page-10\',target_last_page=20,scan_floor_page=7 WHERE native_id=\'100\';UPDATE forum_urls SET next_at=2,completed_at=1 WHERE native_id=\'200\'");return s;}\ntest(\'new discovery backlog does not starve a backfill cursor or an incremental poll\',async()=>{const s=await fixture();try{const rows=s.ready(site,4);assert.equal(rows.length,4);assert(rows.some(r=>r.native_id===\'100\'));assert(rows.some(r=>r.native_id===\'200\'));assert(rows.some(r=>Number(r.native_id)<100));assert.equal(new Set(rows.map(r=>r.native_id)).size,4);const before=s.db.prepare("SELECT resume_url,target_last_page,scan_floor_page FROM forum_urls WHERE native_id=\'100\'").get();s.ready(site,4);assert.deepEqual(s.db.prepare("SELECT resume_url,target_last_page,scan_floor_page FROM forum_urls WHERE native_id=\'100\'").get(),before);}finally{s.close();}});\ntest(\'one-slot selection rotates the three kinds of work and excludes future or other-site tasks\',async()=>{const s=await fixture();try{s.enqueue(\'other.test\',\'https://other.test/threads/a.999\',\'999\');s.db.prepare("UPDATE forum_urls SET next_at=? WHERE native_id=\'50\'").run(Date.now()+600000);const selected=Array.from({length:3},()=>s.ready(site,1)[0]);assert(selected.some(r=>r.native_id===\'100\'));assert(selected.some(r=>r.native_id===\'200\'));assert(selected.every(r=>r.site===site&&r.native_id!==\'50\'));assert.equal(s.hasUnscheduled(site),true);assert.deepEqual(s.ready(site,0),[]);assert.throws(()=>s.ready(site,-1),/FORUM_INVALID_READY_LIMIT/);}finally{s.close();}});\ntest(\'each class keeps FIFO order and an empty class does not waste available slots\',async()=>{const s=await ForumState.open(\':memory:\');try{for(const n of [\'3\',\'1\',\'2\'])s.enqueue(site,\'https://forum.test/threads/a.\'+n,n);s.db.exec("UPDATE forum_urls SET seen=CAST(native_id AS INTEGER),next_at=0");assert.deepEqual(s.ready(site,10).map(r=>r.native_id),[\'1\',\'2\',\'3\']);assert.equal(s.hasUnscheduled(site),true);s.db.exec(\'UPDATE forum_urls SET next_at=1\');assert.equal(s.hasUnscheduled(site),false);assert.equal(s.ready(site,10).length,3);}finally{s.close();}});\ntest(\'non-priority publishers with an initial backlog receive catchup rounds, while full rounds keep every publisher\',async()=>{const make=(domain,priority)=>({domain,priority,homepage:\'https://\'+domain,seeds:[],allowedHosts:[domain]}),sites=[make(\'priority.test\',1),make(\'backlog.test\',0),make(\'ordinary.test\',0)],calls=[],backlog=new Set([\'backlog.test\']),state={setSince:()=>{},hasUnscheduled:s=>backlog.has(s),ready:()=>[]},runtime=new ForumRuntime({state,sites,transport:{close:async()=>{}}});runtime.seeds=async s=>calls.push(s.domain);await runtime.round(1);assert.deepEqual(new Set(calls),new Set([\'priority.test\',\'backlog.test\']));calls.length=0;backlog.clear();await runtime.round(2);assert.deepEqual(calls,[\'priority.test\']);calls.length=0;await runtime.round(5);assert.deepEqual(new Set(calls),new Set(sites.map(s=>s.domain)));});\n')]:path.write_text(content,encoding='utf-8');os.chmod(path,0o644)
